.diagram-search-open { position: absolute; z-index: 14; right: 20px; top: 64px; padding: var(--space-3) var(--space-6); border: 1px solid var(--gutter); border-radius: var(--radius-md); background: var(--surface-raised); color: var(--fg); cursor: pointer; }
.diagram-search-panel { position: absolute; z-index: 30; right: 16px; top: 64px; width: min(420px, calc(100% - 32px)); max-height: calc(100% - 90px); display: flex; flex-direction: column; gap: var(--space-5); padding: var(--space-7); box-sizing: border-box; border: 1px solid var(--gutter); border-radius: var(--radius-lg); background: var(--surface-raised); box-shadow: 0 8px 30px color-mix(in srgb, var(--shadow-color) 53.333%, transparent); color: var(--fg); font: var(--text-md) var(--font-mono); }
.diagram-search-panel header, .diagram-search-options { display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); }
.diagram-search-options { flex-wrap: wrap; }
.diagram-search-panel button, .diagram-search-panel select, .diagram-search-panel input[type=search] { font: inherit; background: var(--surface-app); color: var(--fg); border: 1px solid var(--gutter); border-radius: var(--radius-sm); padding: 5px; }
.diagram-search-panel input[type=search] { width: 100%; }
.diagram-search-query { display: flex; gap: var(--space-3); }
.diagram-search-query input { min-width: 0; }
.diagram-search-panel label { display: flex; align-items: center; gap: 5px; }
.diagram-search-panel small, .diagram-search-panel p { color: var(--muted); margin: 0; }
.diagram-search-results { overflow: auto; min-height: 0; }
.diagram-search-results h3 { font: var(--text-md) var(--font-mono); color: var(--accent-cyan); margin: 14px 0 6px; overflow-wrap: anywhere; }
.diagram-search-results h4 { color: var(--muted); font: var(--text-xs) var(--font-mono); margin: 10px 0 4px; overflow-wrap: anywhere; }
.diagram-search-results h3 + h4 { margin-top: 4px; }
.diagram-search-results button { display: flex; gap: var(--space-5); width: 100%; border: 0; padding: var(--space-3); text-align: left; cursor: pointer; background: transparent; }
.diagram-search-results button:hover, .diagram-search-results button.is-current { background: var(--surface-hover); }
.diagram-search-results code { white-space: pre-wrap; overflow-wrap: anywhere; min-width: 0; font: inherit; }
.diagram-search-line-number { color: var(--muted); min-width: 3ch; text-align: right; }
.diagram-search-results mark { background: var(--accent-warning); color: var(--surface-raised); }
.diagram-search-highlight { position: absolute; z-index: 7; pointer-events: none; background: color-mix(in srgb, var(--accent-warning) 30.000%, transparent); outline: 1px solid var(--accent-warning); }
.diagram-search-highlight.is-current { background: color-mix(in srgb, var(--accent-warning) 55.000%, transparent); outline-width: 2px; }
.window-panel ~ .diagram-search-panel { z-index: 40; }
